parameters.jsonOutput:
={{ (() => {
const log = (typeof $json === 'object' && $json !== null) ? $json : {};
let incomingEmails = [];
try { incomingEmails = $('IMAP: Povuci nove emailove iz Inboxa1').all().map(item => item.json).filter(Boolean); } catch (_) {}

const recipient = String(log.recipient || '').trim().toLowerCase();
const sentAt = new Date(log.contacted_at || log.$createdAt || 0);
let matchedReply = null;
let bounceReason = '';

for (const email of incomingEmails) {
  const from = typeof email.from === 'string'
    ? email.from
    : (email.from?.text || email.from?.value?.map(item => item.address || '').join(' ') || '');
  const subject = String(email.subject || '');
  const body = [email.text, email.textPlain, email.html, email.textHtml, email.body, email.message]
    .filter(value => typeof value === 'string')
    .join('\n');
  const plainBody = body.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ');
  const receivedAt = new Date(email.date || email.headers?.date || Date.now());
  if (!Number.isNaN(sentAt.getTime()) && receivedAt.getTime() < sentAt.getTime() - 300000) continue;

  const isBounce = /mailer-daemon|postmaster|undelivered(?: mail)?|returned to sender|delivery (?:has )?failed|delivery status notification|failure notice/i.test(from + ' ' + subject)
    || /final-recipient:|original-recipient:|diagnostic-code:/i.test(plainBody);
  const bouncedRecipient = plainBody.match(/(?:final-recipient|original-recipient)\s*:\s*(?:rfc822\s*;\s*)?([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i)?.[1]?.toLowerCase()
    || plainBody.match(/(?:to|recipient|for)\s*[:<]\s*<?([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i)?.[1]?.toLowerCase();
  if (isBounce && recipient && bouncedRecipient === recipient) {
    const diagnostic = plainBody.match(/diagnostic-code\s*:\s*[^;]*;?\s*([^\r\n]+)/i)?.[1]
      || plainBody.match(/\b[45]\d\d(?:[ .]\d\.\d\.\d)?[^\r\n]*/)?.[0]
      || subject;
    bounceReason = String(diagnostic || 'Bounce: poruka nije isporučena').replace(/\s+/g, ' ').trim().slice(0, 500);
    break;
  }
  if (!isBounce && recipient && from.toLowerCase().includes(recipient)) {
    matchedReply = email;
    break;
  }
}

const fourDaysAgo = Date.now() - 4 * 24 * 60 * 60 * 1000;
return {
  log,
  has_replied: Boolean(matchedReply),
  is_bounced: Boolean(bounceReason),
  bounce_reason: bounceReason,
  is_ready_for_whatsapp: !Number.isNaN(sentAt.getTime()) && sentAt.getTime() <= fourDaysAgo,
  is_imap_event: incomingEmails.length > 0,
  reply_subject: matchedReply?.subject || '',
  reply_date: matchedReply?.date || '',
  reply_from: typeof matchedReply?.from === 'object' ? (matchedReply?.from?.text || matchedReply?.from?.value?.[0]?.address || '') : (matchedReply?.from || '')
};
})() }}

