const defaultBody = `Poštovani,\n\nPrateći kompanije u sektoru ${cleanIndustry} na području ${cleanCity}, naš tim je analizirao mogućnosti za unapređenje Vašeg digitalnog poslovanja (${company.website || cleanCompanyName}).\n\nU digitalnoj agenciji ED Vision pomažemo kompanijama kroz digitalnu transformaciju i digitalizaciju procesa:\n• Izrada modernih web stranica i web shopova prilagođenih Vašoj industriji\n• Automatizacija prikupljanja upita i digitalni katalozi proizvoda\n• Efikasnija komunikacija sa novim klijentima i povećanje prodaje\n\nBili bismo slobodni da Vam predstavimo kratak prijedlog koncepta. Da li biste bili zainteresovani za kratak telefonski razgovor ili sastanak u toku sedmice?\n\nSrdačan pozdrav,`;

const finalAnalysis = (parsed?.analysis && Array.isArray(parsed.analysis) && parsed.analysis.length > 0)
  ? parsed.analysis
  : ['Digitalizacija poslovnih procesa i upita', 'Mogućnost uvođenja modernog web shopa / kataloga', 'Digitalna transformacija i rast prodaje'];

let finalSubject = (parsed?.email_subject && String(parsed.email_subject).trim())
  ? String(parsed.email_subject).trim()
  : defaultSubject;

let finalBody = (parsed?.email_body && String(parsed.email_body).trim())
  ? String(parsed.email_body).trim()
  : defaultBody;

if (finalBody) {
  finalBody = finalBody
    // Uklanjanje robotskih i doslovno prevedenih fraza
    .replace(/Nadam\s*se\s*da\s*vas\s*(?:ova\s*poruka|ovaj\s*e-?mail)\s*(?:pronalazi|zatiče)[^.\n]*[.\n]/gi, '')
    .replace(/Nadam\s*se\s*da\s*ste\s*(?:dobro|u\s*dobrom\s*raspoloženju)[^.\n]*[.\n]/gi, '')
